package com.termux.app.workspace;
import android.app.Application;import android.content.*;import android.database.*;import android.net.Uri;import android.os.ParcelFileDescriptor;import android.provider.MediaStore;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.shadows.ShadowContentResolver;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class ImageGalleryExportTest {
 Path root;File original;
 static byte[] gif(){byte[] one=Base64.getDecoder().decode("R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7");ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(one,0,19);out.write(one,19,one.length-20);out.write(one,19,one.length-20);out.write(59);return out.toByteArray();}
 @Before public void setup()throws Exception{root=Files.createTempDirectory(Path.of(System.getProperty("java.io.tmpdir")),"gallery-fixture-");original=root.resolve("original.gif").toFile();Files.write(original.toPath(),gif());}
 static final class Entry {ContentValues values;String name;ByteArrayOutputStream bytes=new ByteArrayOutputStream();boolean published;}
 static class Store implements ImageGalleryExport.Store {
  final LinkedHashMap<Uri,Entry> entries=new LinkedHashMap<>();final List<Uri> deleted=new ArrayList<>();int serial,opened;String fail="";AtomicBoolean cancelled=new AtomicBoolean();
  public Uri insert(ContentValues values)throws Exception{if(fail.equals("insert"))throw new IOException();if(fail.equals("null"))return null;Entry e=new Entry();e.values=new ContentValues(values);String name=values.getAsString(MediaStore.Images.Media.DISPLAY_NAME),base=name;int dot=base.lastIndexOf('.'),number=1;while(true){final String candidate=name;if(entries.values().stream().noneMatch(v->v.name.equals(candidate)))break;name=base.substring(0,dot)+"-"+(++number)+base.substring(dot);}e.name=name;Uri uri=Uri.parse("content://media/external/images/media/"+(++serial));entries.put(uri,e);return uri;}
  public OutputStream open(Uri uri)throws Exception{opened++;if(fail.equals("open"))throw new IOException();if(fail.equals("stream-null"))return null;return new FilterOutputStream(entries.get(uri).bytes){public void write(byte[] b,int off,int len)throws IOException{if(fail.equals("write"))throw new IOException();out.write(b,off,len);if(fail.equals("cancel"))cancelled.set(true);}public void close()throws IOException{if(fail.equals("close"))throw new IOException();super.close();}};}
  public ImageGalleryExport.Description describe(Uri uri)throws Exception{if(fail.equals("describe"))throw new IOException();Entry e=entries.get(uri);return new ImageGalleryExport.Description(fail.equals("extension")?"wrong.jpg":e.name,fail.equals("mime")?"image/jpeg":e.values.getAsString(MediaStore.Images.Media.MIME_TYPE));}
  public int publish(Uri uri)throws Exception{if(fail.equals("publish"))throw new IOException();if(fail.equals("update-zero"))return 0;assertEquals(Integer.valueOf(1),entries.get(uri).values.getAsInteger(MediaStore.Images.Media.IS_PENDING));entries.get(uri).published=true;return 1;}
  public boolean remove(Uri uri){deleted.add(uri);entries.remove(uri);return !fail.equals("cleanup");}
 }
 @Test public void modernAnimatedGifKeepsExactOriginalMimeExtensionAndSeparateNames()throws Exception{Store store=new Store();ImageGalleryExport.Result first=ImageGalleryExport.save(store,true,null,original,"motion.GIF",()->false),second=ImageGalleryExport.save(store,true,null,original,"motion.GIF",()->false);assertNotEquals(first.name,second.name);assertEquals("motion.GIF",first.name);assertTrue(second.name.endsWith(".GIF"));assertNotEquals(first.uri,second.uri);for(Entry e:store.entries.values()){assertArrayEquals(gif(),e.bytes.toByteArray());assertEquals("image/gif",e.values.getAsString(MediaStore.Images.Media.MIME_TYPE));assertEquals("Pictures/TermuxJobs/",e.values.getAsString(MediaStore.Images.Media.RELATIVE_PATH));assertFalse(e.values.containsKey(MediaStore.Images.Media.DATA));assertTrue(e.published);}assertArrayEquals(gif(),Files.readAllBytes(original.toPath()));assertEquals(2,store.opened);}
 @Test public void everySupportedImageFamilyHasVerifiedMimeAndKeepsExtension()throws Exception{Map<String,byte[]> formats=new LinkedHashMap<>();formats.put("PNG",new byte[]{(byte)137,80,78,71,13,10,26,10});formats.put("jpeg",new byte[]{(byte)255,(byte)216,(byte)255,0});formats.put("jpg",formats.get("jpeg"));formats.put("gif",gif());formats.put("webp","RIFF0000WEBPVP8 ".getBytes());formats.put("bmp",new byte[]{66,77,0,0});formats.put("heic",new byte[]{0,0,0,24,102,116,121,112,104,101,105,99,0,0,0,0});formats.put("heif",new byte[]{0,0,0,24,102,116,121,112,109,105,102,49,0,0,0,0});formats.put("avif",new byte[]{0,0,0,24,102,116,121,112,97,118,105,102,0,0,0,0});for(Map.Entry<String,byte[]> f:formats.entrySet()){Files.write(original.toPath(),f.getValue());Store store=new Store();String name="original."+f.getKey();ImageGalleryExport.Result result=ImageGalleryExport.save(store,true,null,original,name,()->false);assertEquals(name,result.name);assertEquals(ProjectFiles.mime(name),store.entries.get(result.uri).values.getAsString(MediaStore.Images.Media.MIME_TYPE));assertArrayEquals(f.getValue(),store.entries.get(result.uri).bytes.toByteArray());}}
 @Test public void writeClosePublishMetadataAndCancellationFailuresRemoveOnlyOwnRow()throws Exception{for(String fail:new String[]{"insert","null","open","stream-null","write","close","describe","extension","mime","publish","update-zero","cancel"}){Store store=new Store();ImageGalleryExport.Result previous=ImageGalleryExport.save(store,true,null,original,"before.gif",()->false);byte[] preserved=store.entries.get(previous.uri).bytes.toByteArray();store.fail=fail;try{ImageGalleryExport.save(store,true,null,original,"new.gif",store.cancelled::get);fail(fail);}catch(IOException expected){}assertEquals(fail,1,store.entries.size());assertTrue(store.entries.containsKey(previous.uri));assertArrayEquals(preserved,store.entries.get(previous.uri).bytes.toByteArray());assertFalse(store.deleted.contains(previous.uri));assertArrayEquals(gif(),Files.readAllBytes(original.toPath()));}}
 @Test public void legacyExclusiveFilesRegisterInMediaStoreAndCleanFailedOperation()throws Exception{File album=root.resolve("Pictures/TermuxJobs").toFile();assertTrue(album.mkdirs());Path before=album.toPath().resolve("motion.gif");Files.write(before,"PRESERVE_EXISTING".getBytes());Store store=new Store();ImageGalleryExport.Result a=ImageGalleryExport.save(store,false,album,original,"motion.gif",()->false),b=ImageGalleryExport.save(store,false,album,original,"motion.gif",()->false);assertEquals("motion-2.gif",a.name);assertEquals("motion-3.gif",b.name);for(Entry e:store.entries.values()){assertFalse(e.values.containsKey(MediaStore.Images.Media.IS_PENDING));assertFalse(e.values.containsKey(MediaStore.Images.Media.RELATIVE_PATH));assertArrayEquals(gif(),Files.readAllBytes(Path.of(e.values.getAsString(MediaStore.Images.Media.DATA))));}assertEquals(0,store.opened);store.fail="mime";try{ImageGalleryExport.save(store,false,album,original,"motion.gif",()->false);fail();}catch(IOException expected){}assertEquals(2,store.entries.size());assertFalse(Files.exists(album.toPath().resolve("motion-4.gif")));assertEquals("PRESERVE_EXISTING",new String(Files.readAllBytes(before),java.nio.charset.StandardCharsets.UTF_8));}
 @Test public void mismatchInvalidHeaderAndPreCancelledOperationCreateNoEntry()throws Exception{Store store=new Store();try{ImageGalleryExport.save(store,true,null,original,"wrong.png",()->false);fail();}catch(ImageGalleryExport.Failure expected){assertEquals("UNSUPPORTED_IMAGE",expected.code);}try{ImageGalleryExport.save(store,true,null,original,"motion.gif",()->true);fail();}catch(IOException expected){}assertTrue(store.entries.isEmpty());Files.write(original.toPath(),"ARTIFICIAL_INVALID_IMAGE".getBytes());try{ImageGalleryExport.save(store,true,null,original,"bad.gif",()->false);fail();}catch(IOException expected){}assertTrue(store.entries.isEmpty());}
 @Test public void safeLongNameRetainsOriginalExtensionAndCleanupFailureNeverSucceeds()throws Exception{String name=String.join("",Collections.nCopies(100,"Изображение"))+".GIF";ImageGalleryExport.Plan p=ImageGalleryExport.plan(original,name);assertTrue(p.name.endsWith(".GIF"));assertTrue(p.name.getBytes(java.nio.charset.StandardCharsets.UTF_8).length<=200);Store broken=new Store(){public OutputStream open(Uri uri)throws Exception{throw new IOException();}public boolean remove(Uri uri){return false;}};try{ImageGalleryExport.save(broken,true,null,original,"motion.gif",()->false);fail();}catch(ImageGalleryExport.Failure expected){assertEquals("CLEANUP_FAILED",expected.code);}}
 static class Provider extends ContentProvider {final File dir;final Map<Uri,ContentValues> rows=new LinkedHashMap<>();int id;ContentValues inserted,updated;Uri removed;Provider(File dir){this.dir=dir;}public boolean onCreate(){return true;}public String getType(Uri uri){return rows.get(uri).getAsString(MediaStore.Images.Media.MIME_TYPE);}public Uri insert(Uri collection,ContentValues v){assertEquals(MediaStore.Images.Media.getContentUri("external_primary"),collection);inserted=new ContentValues(v);Uri uri=Uri.withAppendedPath(collection,""+(++id));ContentValues row=new ContentValues(v);row.put(MediaStore.Images.Media._ID,id);row.put(MediaStore.Images.Media.DATA,new File(dir,"row-"+id).getAbsolutePath());rows.put(uri,row);return uri;}public int update(Uri uri,ContentValues v,String s,String[] a){updated=new ContentValues(v);rows.get(uri).putAll(v);return 1;}public int delete(Uri uri,String s,String[] a){removed=uri;ContentValues row=rows.remove(uri);if(row==null)return 0;new File(row.getAsString(MediaStore.Images.Media.DATA)).delete();return 1;}public Cursor query(Uri uri,String[] projection,String s,String[] a,String order){MatrixCursor cursor=new MatrixCursor(projection);ContentValues row=rows.get(uri);if(row!=null){Object[] values=new Object[projection.length];for(int n=0;n<values.length;n++)values[n]=row.get(projection[n]);cursor.addRow(values);}return cursor;}public ParcelFileDescriptor openFile(Uri uri,String mode)throws FileNotFoundException{return ParcelFileDescriptor.open(new File(rows.get(uri).getAsString(MediaStore.Images.Media.DATA)),ParcelFileDescriptor.MODE_CREATE|ParcelFileDescriptor.MODE_WRITE_ONLY|ParcelFileDescriptor.MODE_TRUNCATE);}}
 @Test public void androidContentResolverAdapterUsesPendingImageRowAndRawOutput()throws Exception{Provider provider=new Provider(root.toFile());android.content.pm.ProviderInfo info=new android.content.pm.ProviderInfo();info.authority="media";provider.attachInfo(RuntimeEnvironment.application,info);ShadowContentResolver.registerProviderInternal("media",provider);ImageGalleryExport.AndroidStore store=new ImageGalleryExport.AndroidStore(RuntimeEnvironment.application.getContentResolver(),true);ImageGalleryExport.Result result=ImageGalleryExport.save(store,true,null,original,"motion.gif",()->false);assertEquals("image/gif",provider.inserted.getAsString(MediaStore.Images.Media.MIME_TYPE));assertEquals(Integer.valueOf(1),provider.inserted.getAsInteger(MediaStore.Images.Media.IS_PENDING));assertEquals(Integer.valueOf(0),provider.updated.getAsInteger(MediaStore.Images.Media.IS_PENDING));assertArrayEquals(gif(),Files.readAllBytes(Path.of(provider.rows.get(result.uri).getAsString(MediaStore.Images.Media.DATA))));assertTrue(store.remove(result.uri));assertEquals(result.uri,provider.removed);}
}
